USE pet_adoption_network;
CREATE OR REPLACE VIEW Available_Animals_View AS SELECT a.animal_id,a.name,a.species,a.breed,a.age,a.gender,a.size,a.health_status,a.special_needs,s.shelter_name,s.city FROM animals a LEFT JOIN shelters s ON s.shelter_id=a.shelter_id WHERE a.current_status='Available';
CREATE OR REPLACE VIEW Medical_Followup_View AS SELECT m.medical_id,a.animal_id,a.name animal_name,a.species,m.examination_date,m.next_checkup_date,m.follow_up_status,CASE WHEN m.next_checkup_date<CURRENT_DATE AND m.follow_up_status='Pending' THEN 'OVERDUE' WHEN m.next_checkup_date>=CURRENT_DATE AND m.follow_up_status='Pending' THEN 'UPCOMING' ELSE 'NO ACTION' END followup_state FROM medical_records m JOIN animals a ON a.animal_id=m.animal_id;
CREATE OR REPLACE VIEW Adoption_Application_Summary_View AS SELECT aa.application_id,a.name animal_name,a.species,ad.full_name adopter_name,aa.application_date,aa.application_status,hv.visit_status,hv.approval_recommendation FROM adoption_applications aa JOIN animals a ON a.animal_id=aa.animal_id JOIN adopters ad ON ad.adopter_id=aa.adopter_id LEFT JOIN home_visits hv ON hv.application_id=aa.application_id;
